/* sync.js — PostgREST fetch wrappers, offline queue, replay.
 *
 * Every change from the UI writes to the local store first and renders
 * immediately, then calls SyncQueue#enqueue to schedule the network write.
 * The queue replays on reconnect. Writes are idempotent, keyed by a
 * client-generated UUID (the row's own `id`, already generated by
 * task-store.js / rhythms.js / lists.js at creation time), so a queue that
 * gets replayed twice — e.g. the app closes after applying an op but
 * before removing it from the queue — cannot double-apply it.
 *
 * Conflict handling is last-write-wins PER FIELD, not per row: every
 * `update` op carries only the fields that actually changed, and PostgREST
 * PATCH only touches the columns named in the body. Two devices editing
 * different fields of the same task concurrently both land; only a
 * genuinely simultaneous edit of the *same* field can lose one side. See
 * the design spec, "Sync and offline".
 *
 * This module has no browser-only code at its core — createPostgrestClient
 * and SyncQueue both take their I/O (fetch, storage) as plain arguments, so
 * tests/sync.test.js exercises the real logic against a fake fetch with no
 * network and no real Supabase project. The one browser-specific piece,
 * IndexedDBQueueStore, is an adapter behind the same tiny interface
 * (add/list/remove) and is never imported by the tests.
 */
'use strict';

export class PostgrestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'PostgrestError';
    this.status = status;
  }
}

/**
 * A thin PostgREST client: insert (upsert, for idempotent replay), update
 * (partial PATCH by id, for per-field last-write-wins), remove (idempotent
 * DELETE by id — deleting an already-gone row is not an error).
 *
 * @param {{ url: string, anonKey: string, getAccessToken?: () => string|null, fetchImpl?: typeof fetch }} config
 */
export function createPostgrestClient({ url, anonKey, getAccessToken, fetchImpl }) {
  const doFetch = fetchImpl ?? globalThis.fetch;

  async function request(table, { method = 'GET', path = '', body, prefer } = {}) {
    const token = (getAccessToken && getAccessToken()) || anonKey;
    const headers = {
      apikey: anonKey,
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    };
    if (prefer) headers.Prefer = prefer;
    const res = await doFetch(`${url}/rest/v1/${table}${path}`, {
      method,
      headers,
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) {
      let text = '';
      try { text = await res.text(); } catch { /* ignore */ }
      throw new PostgrestError(`${method} ${table}${path} failed: ${res.status} ${text}`, res.status);
    }
    if (res.status === 204) return null;
    try { return await res.json(); } catch { return null; }
  }

  return {
    insert(table, row) {
      // merge-duplicates on the primary key makes a replayed insert of the
      // same client-generated id a no-op overwrite rather than a 23505
      // unique-violation error.
      return request(table, {
        method: 'POST',
        body: row,
        prefer: 'resolution=merge-duplicates,return=representation',
      });
    },
    update(table, id, patch) {
      return request(table, {
        method: 'PATCH',
        path: `?id=eq.${encodeURIComponent(id)}`,
        body: patch,
        prefer: 'return=representation',
      });
    },
    remove(table, id) {
      return request(table, { method: 'DELETE', path: `?id=eq.${encodeURIComponent(id)}` });
    },
  };
}

/** In-memory queue store — the default, and what tests use. */
export class MemoryQueueStore {
  constructor() {
    this._ops = [];
  }
  async add(op) { this._ops.push(op); }
  async list() { return [...this._ops]; }
  async remove(opId) { this._ops = this._ops.filter((o) => o.id !== opId); }
  async clear() { this._ops = []; }
}

/**
 * IndexedDB-backed queue store, so the queue survives a reload while
 * offline. Same {add, list, remove} interface as MemoryQueueStore. Only
 * constructed by ui/*.js in a real browser — never touched by node:test.
 */
export class IndexedDBQueueStore {
  constructor(dbName = 'todo-app-sync-queue', storeName = 'ops') {
    this.dbName = dbName;
    this.storeName = storeName;
    this._dbPromise = null;
  }

  _open() {
    if (this._dbPromise) return this._dbPromise;
    this._dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(this.dbName, 1);
      req.onupgradeneeded = () => {
        req.result.createObjectStore(this.storeName, { keyPath: 'id' });
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
    return this._dbPromise;
  }

  async add(op) {
    const db = await this._open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      tx.objectStore(this.storeName).put(op);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  async list() {
    const db = await this._open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readonly');
      const req = tx.objectStore(this.storeName).getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  async remove(opId) {
    const db = await this._open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.storeName, 'readwrite');
      tx.objectStore(this.storeName).delete(opId);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
}

/** A 4xx other than 429 is a permanent failure (bad request, RLS denial,
 * validation) — retrying it unchanged will never succeed, so it is
 * dropped from the queue rather than blocking everything behind it.
 * Anything else (network failure, 5xx, 429) is treated as transient. */
function isPermanentFailure(err) {
  return err instanceof PostgrestError && err.status >= 400 && err.status < 500 && err.status !== 429;
}

/**
 * The offline queue: enqueue() persists an op and renders can proceed
 * immediately; replay() drains the queue against the network, stopping at
 * the first transient failure so remaining ops stay queued for the next
 * reconnect rather than being attempted (and failing) one by one.
 */
export class SyncQueue {
  /**
   * @param {{ client: ReturnType<typeof createPostgrestClient>, store?: object, onDropped?: (op:object, err:Error) => void }} opts
   */
  constructor({ client, store, onDropped } = {}) {
    this.client = client;
    this.store = store ?? new MemoryQueueStore();
    this.onDropped = onDropped;
  }

  /**
   * @param {{ id: string, type: 'insert'|'update'|'delete', table: string, rowId: string, payload?: object }} op
   * @param {{ replay?: boolean }} [opts] - set replay:false to only persist, e.g. while known offline
   */
  async enqueue(op, opts = {}) {
    await this.store.add(op);
    if (opts.replay !== false) return this.replay();
    return { applied: [], failed: [], stoppedAt: null };
  }

  /**
   * Applies every queued op in order, idempotently. Stops at the first
   * transient (network/5xx) failure, leaving it and everything after it in
   * the queue for the next call. Permanent (4xx) failures are dropped and
   * reported via onDropped, but do not block the rest of the queue.
   */
  async replay() {
    const pending = await this.store.list();
    const result = { applied: [], failed: [], stoppedAt: null };
    for (const op of pending) {
      try {
        await this._apply(op);
        await this.store.remove(op.id);
        result.applied.push(op.id);
      } catch (err) {
        if (isPermanentFailure(err)) {
          await this.store.remove(op.id);
          result.failed.push({ opId: op.id, error: err });
          if (this.onDropped) this.onDropped(op, err);
          continue;
        }
        result.stoppedAt = op.id;
        break;
      }
    }
    return result;
  }

  async _apply(op) {
    if (op.type === 'insert') return this.client.insert(op.table, op.payload);
    if (op.type === 'update') return this.client.update(op.table, op.rowId, op.payload);
    if (op.type === 'delete') return this.client.remove(op.table, op.rowId);
    throw new Error(`unknown sync op type: ${op.type}`);
  }
}
